org.oie.fhir.fml.FhirFmlTransformStep.mapSource:
map "http://example.org/fhir/oru2fhir/StructureMap/OruR01ToPatient" = "OruR01ToPatient"

// Démo : le PID d'un ORU^R01 devient un Patient conforme à ExampleLabPatient (/fhir-ig), comme
// le canal « ORU R01 vers Patient FHIR » du Profile Mapper, mais en FML.
// Source : le modèle logique générique d'OIE (OieMessage). Un nœud se désigne par son nom
// (PID, PID.5) ou par sa position (composant 1, 2…) ; sa valeur est dans value.

uses "http://oie.org/fhir/StructureDefinition/OieMessage" alias OieMessage as source
uses "http://example.org/fhir/oru2fhir/StructureDefinition/ExampleLabPatient" alias Patient as target

group OruR01ToPatient(source src : OieMessage, target patient : Patient) {
  src -> patient.meta as meta, meta.profile = 'http://example.org/fhir/oru2fhir/StructureDefinition/ExampleLabPatient' "profile";
  src.node as pid where name = 'PID' then {
    // L'IPP : le PID-3 dont le type d'identifiant (composant 5) vaut PI.
    pid.node as cx where name = 'PID.3' and node.where(position = 5 and value = 'PI').exists() then {
      cx.node as number where position = 1 -> patient.identifier as identifier then {
        number -> identifier.system = 'http://example.org/fhir/oru2fhir/sid/ipp' "ipp-system";
        number.value as v -> identifier.value = v "ipp-value";
      } "ipp";
    } "identifiers";
    // Chaque nom (PID-5 répétable) : nom de famille, prénoms, usage d'après le type de nom.
    pid.node as xpn where name = 'PID.5' -> patient.name as name then {
      xpn.node as family where position = 1 then { family.value as v -> name.family = v "family"; } "family-name";
      xpn.node as given where position = 2 then { given.value as v -> name.given = v "given"; } "given-name";
      xpn.node as second where position = 3 then { second.value as v -> name.given = v "second-given"; } "second-given-name";
      xpn.node as type where position = 7 and value = 'L' -> name.use = 'official' "use-official";
      xpn.node as type where position = 7 and value = 'D' -> name.use = 'usual' "use-usual";
      xpn.node as type where position = 7 and value = 'M' -> name.use = 'maiden' "use-maiden";
    } "name";
    // Sexe : table HL7 0001 vers administrative-gender, par la ConceptMap de /fhir-ig.
    pid.node as sex where name = 'PID.8' then {
      sex.node as code where position = 1 then {
        code.value as v -> patient.gender = translate(v, 'http://example.org/fhir/oru2fhir/ConceptMap/v2-0001-to-gender', 'code') "gender";
      } "sex-code";
    } "sex";
    // Date de naissance : AAAAMMJJ vers AAAA-MM-JJ.
    pid.node as dob where name = 'PID.7' then {
      dob.node as time where position = 1 then {
        time.value as v where v.length() >= 8 -> patient.birthDate = (v.substring(0, 4) & '-' & v.substring(4, 2) & '-' & v.substring(6, 2)) "birthDate";
      } "birth-time";
    } "date-of-birth";
  } "pid";
}

com.mirth.connect.plugins.javascriptstep.script:
var end = channelMap.get('__fhirMapperBuildFinishedNano') || java.lang.System.nanoTime();
var elapsed = Number(end) - Number(channelMap.get('__demoTransfoDebut'));
channelMap.put('TRANSFO_MS', Math.round(elapsed / 1000) / 1000);
channelMap.put('__demoEtape', 'VALIDATION_FHIR_SORTIE');

channel.preprocessingScript:
// Réinitialisé pour chaque message, y compris après retraitement.
channelMap.put('TOTAL_MS', 0);
channelMap.remove('TRANSFO_MS');
channelMap.put('ERREUR_ETAPE', 'OK');
channelMap.put('__demoEtape', 'LECTURE_HL7');
channelMap.remove('__fhirMapperPhase');
channelMap.remove('__fhirMapperBuildFinishedNano');
channelMap.remove('__fhirMapperValidationNanos');
return message;

channel.postprocessingScript:
// Exécuté après les destinations, aussi après une erreur de lecture/transformation/validation.
var source = message.getConnectorMessages().get(java.lang.Integer.valueOf(0));
var total = Math.max(0, java.lang.System.currentTimeMillis() - source.getReceivedDate().getTimeInMillis());
var errorLabel = 'OK';
var connectors = message.getConnectorMessages().values().iterator();
while (connectors.hasNext()) {
    var cm = connectors.next();
    var error = cm.getProcessingError() || cm.getResponseError() || cm.getPostProcessorError();
    if (error) {
        var stage = cm.getMetaDataId() == 0
            ? String(source.getChannelMap().get('__fhirMapperPhase') == 'VALIDATION' ? 'VALIDATION_FHIR_SORTIE' : (source.getChannelMap().get('__demoEtape') || 'LECTURE_HL7'))
            : 'SORTIE / ' + cm.getConnectorName();
        var details = String(error);
        var issue = /(?:^|\n)(?:error|fatal)\s+@?\s*([^\r\n]+)/i.exec(details);
        var cause = /DETAILS:\s*([^\r\n]+)/.exec(details);
        details = cause ? cause[1] : issue ? issue[1] : details.split(/\r?\n/)[0];
        errorLabel = (stage + ': ' + details).substring(0, 255);
        break;
    }
}

// OIE enregistre les métadonnées avant le postprocesseur : mettre à jour la ligne source
// via son DAO pour conserver le temps complet et les erreurs survenues en sortie.
var values = new java.util.HashMap();
values.put('TOTAL_MS', new java.math.BigDecimal(String(total)));
var transfo = source.getChannelMap().get('TRANSFO_MS');
var finished = source.getChannelMap().get('__fhirMapperBuildFinishedNano');
if (transfo == null && finished != null) {
    transfo = Math.round((Number(finished) - Number(source.getChannelMap().get('__demoTransfoDebut'))) / 1000) / 1000;
}
if (transfo != null) {
    values.put('TRANSFO_MS', new java.math.BigDecimal(String(transfo)));
}
values.put('ERREUR_ETAPE', errorLabel);
var record = new Packages.com.mirth.connect.donkey.model.message.ConnectorMessage();
record.setChannelId(channelId);
record.setMessageId(message.getMessageId());
record.setMetaDataId(0);
record.setMetaDataMap(values);
var dao = Packages.com.mirth.connect.donkey.server.Donkey.getInstance().getDaoFactory().getDao();
var committed = false;
try {
    dao.storeMetaData(record, dao.getMetaDataColumns(channelId));
    dao.commit();
    committed = true;
} finally {
    try {
        if (!committed) dao.rollback();
    } finally {
        dao.close();
    }
}
return;
